addBox.example:
// client
const { Collision } = kcds.world;
const { Vector3 } = kcds.math;

const wall = Collision.addBox({
  center: new Vector3(1533, 2143, 17.1),
  size: new Vector3(6, 0.3, 3),
  rotation: { x: 0, y: 0, z: 30 },
});
wall.set({ size: new Vector3(8, 0.3, 3) });
wall.remove();

addBox.exampleCs:
// client

var wall = Collision.AddBox(new { center = new Vector3(1533, 2143, 17.1), size = new Vector3(6, 0.3, 3), rotation = new { x = 0, y = 0, z = 30 } });
wall.Call("set", new { size = new Vector3(8, 0.3, 3) });
wall.Call("remove");

all.example:
// client
for (const box of kcds.world.Collision.all()) {
  box.remove();
}

all.exampleCs:
// client
foreach (var box in Collision.All())
{
    box.Call("remove");
}
